const simRooms = ["kamar_1", "kamar_2", "ruang_kerja", "dapur"];
let previous = global.get('smartHomeData') || {};

// Cek apakah ada data MQTT real untuk ruang_tamu
let mqttData = global.get('smartHomeDataMQTT');
let mqttFresh = mqttData && mqttData.timestamp &&
    (Date.now() - new Date(mqttData.timestamp).getTime()) < 10000;

let data = { rooms: {}, pintu_masuk: {}, timestamp: new Date().toISOString() };

// Ruang Tamu: real dari DHT11 jika ada, fallback simulasi
if (mqttFresh) {
    data.rooms.ruang_tamu = {
        temperature: mqttData.rooms.ruang_tamu.temperature,
        humidity: mqttData.rooms.ruang_tamu.humidity,
        ac_status: (previous.rooms && previous.rooms.ruang_tamu)
            ? previous.rooms.ruang_tamu.ac_status : false
    };
} else {
    let t = +(27 + (Math.random() * 4 - 2)).toFixed(1);
    let h = +(65 + (Math.random() * 10 - 5)).toFixed(1);
    data.rooms.ruang_tamu = {
        temperature: Math.max(20, Math.min(35, t)),
        humidity: Math.max(40, Math.min(95, h)),
        ac_status: (previous.rooms && previous.rooms.ruang_tamu)
            ? previous.rooms.ruang_tamu.ac_status : false
    };
}

// 4 ruangan lain: simulasi random
simRooms.forEach(room => {
    let t = +(27 + (Math.random() * 4 - 2)).toFixed(1);
    let h = +(65 + (Math.random() * 10 - 5)).toFixed(1);
    data.rooms[room] = {
        temperature: Math.max(20, Math.min(35, t)),
        humidity: Math.max(40, Math.min(95, h)),
        ac_status: (previous.rooms && previous.rooms[room])
            ? previous.rooms[room].ac_status : false
    };
});

data.pintu_masuk = { motion_detected: Math.random() < 0.2 };

msg.payload = data;
global.set('smartHomeData', data);
return msg;

let fileContent = (typeof msg.payload === 'string') ? msg.payload : '';
let dataBaru = global.get('smartHomeData');

let history = [];
try {
    if (fileContent && fileContent.trim().length > 0) {
        history = JSON.parse(fileContent);
    }
} catch (e) {
    node.warn('File histori tidak valid, mulai dari kosong.');
    history = [];
}

if (!Array.isArray(history)) { history = []; }

history.push({
    timestamp: dataBaru.timestamp,
    motion_detected: dataBaru.pintu_masuk.motion_detected,
    rooms: {
        ruang_tamu: {
            temperature: dataBaru.rooms.ruang_tamu.temperature,
            humidity: dataBaru.rooms.ruang_tamu.humidity
        },
        kamar_1: {
            temperature: dataBaru.rooms.kamar_1.temperature,
            humidity: dataBaru.rooms.kamar_1.humidity
        },
        kamar_2: {
            temperature: dataBaru.rooms.kamar_2.temperature,
            humidity: dataBaru.rooms.kamar_2.humidity
        },
        ruang_kerja: {
            temperature: dataBaru.rooms.ruang_kerja.temperature,
            humidity: dataBaru.rooms.ruang_kerja.humidity
        },
        dapur: {
            temperature: dataBaru.rooms.dapur.temperature,
            humidity: dataBaru.rooms.dapur.humidity
        }
    }
});

if (history.length > 200) {
    history = history.slice(history.length - 200);
}

msg.payload = JSON.stringify(history, null, 2);
return msg;

let dhtData = msg.payload;

let current = global.get('smartHomeData') || { rooms: {} };

current.rooms.ruang_tamu = {
    temperature: dhtData.temperature,
    humidity: dhtData.humidity,
    ac_status: (current.rooms.ruang_tamu) ? current.rooms.ruang_tamu.ac_status : false
};

global.set('smartHomeDataMQTT', {
    rooms: { ruang_tamu: { temperature: dhtData.temperature, humidity: dhtData.humidity } },
    timestamp: new Date().toISOString()
});

global.set('smartHomeData', current);

return null;

let data = global.get('smartHomeData');
if (!data) {
    msg.payload = { error: 'Data belum tersedia' };
} else {
    msg.payload = data;
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

let fileContent = (typeof msg.payload === 'string') ? msg.payload : '';
let history = [];
try {
    if (fileContent && fileContent.trim().length > 0) {
        history = JSON.parse(fileContent);
    }
} catch (e) {
    history = [];
}
if (!Array.isArray(history)) { history = []; }
msg.payload = history;
msg.headers = { 'Content-Type': 'application/json' };
return msg;
